 * stderr by default, so a command's stdout, its --json object among it, holds only what it prints.
 */
export declare function processIo({ input, output, }?: {
    [K in keyof Terminal]?: Terminal[K] | undefined;
}): CliIo;
export {};

// cli/run.d.ts
